import {socialAPI} from './api.mjs';
export default {async fetch(request,env){const u=new URL(request.url);if(u.pathname.startsWith('/api/social/'))return socialAPI(request,env);if(request.method!=='GET'&&request.method!=='HEAD')return new Response('Method not allowed',{status:405});let target=u.pathname;if(target==='/'||target.startsWith('/social')||target.startsWith('/embed/')||target.startsWith('/admin/')){if(!/\.(?:css|js|mjs|png|svg|jpg|ttf|woff|woff2|otf|txt)$/.test(target))target='/social/';}const response=await env.ASSETS.fetch(new Request(new URL(target,u.origin),request));const secured=new Response(response.body,response);secured.headers.set('X-Content-Type-Options','nosniff');secured.headers.set('Referrer-Policy','strict-origin-when-cross-origin');secured.headers.set('Content-Security-Policy',"default-src 'self'; script-src 'self'; style-src 'self' https://fonts.googleapis.com; font-src 'self' https:; img-src 'self' data: blob: https:; media-src 'self' blob:; connect-src 'self' https://xbtesports-calendar-public.smithrock87.workers.dev; frame-src 'self' https://xbtesports-social.smithrock87.workers.dev https://battlefy.com https://www.youtube.com https://player.twitch.tv; base-uri 'self'; form-action 'self'");return secured;}};
