import {one,rows} from './core.mjs';
export async function telemetry(db,userId){const matches=(await rows(db,"SELECT m.data,t.title,t.slug,t.updated_at FROM matches m JOIN tournaments t ON t.id=m.tournament_id WHERE t.status<>'Draft' AND m.status='Completed' AND EXISTS(SELECT 1 FROM json_each(m.data,'$.players') WHERE value=?) ORDER BY t.updated_at DESC,m.round DESC LIMIT 1000",userId)).map(m=>({...JSON.parse(m.data),tournament:m.title,slug:m.slug})).filter(m=>!m.bye);
 const wins=matches.filter(m=>m.winner===userId).length,losses=matches.filter(m=>m.winner&&m.winner!==userId).length,placements=matches.flatMap(m=>m.result?.filter(p=>p.id===userId).map(p=>p.placement)||[]);let streak=0,best=0,run=0;for(const m of [...matches].reverse()){run=m.winner===userId?run+1:0;best=Math.max(best,run);}for(const m of matches){if(m.winner!==userId)break;streak++;}
 const entries=await one(db,"SELECT count(*) n FROM registrations r JOIN tournaments t ON t.id=r.tournament_id WHERE r.user_id=? AND t.status<>'Draft' AND r.status='approved'",userId),champions=await one(db,"SELECT count(*) n FROM brackets b JOIN tournaments t ON t.id=b.tournament_id WHERE json_extract(b.data,'$.champion')=? AND t.status='Completed'",userId);
 return {stats:{matches:matches.length,wins,losses,winPercentage:matches.length?Math.round(wins/matches.length*100):0,entries:entries.n,tournamentWins:champions.n,currentStreak:streak,bestStreak:best,averagePlacement:placements.length?placements.reduce((a,b)=>a+b,0)/placements.length:null},recent:matches.slice(0,10)};
}
